//! Code generated by `TrivialType` derive must use `assert!` of `core`, a local macro with the same
//! name must not replace its assertions

use ab_io_type::trivial_type::TrivialType;

// Doesn't check anything
#[expect(unused_macros, reason = "Generated code must not use it")]
macro_rules! assert {
    ($($tokens:tt)*) => {
        ()
    };
}

// Padding is also rejected by metadata decoding, but the error must be the one of the padding
// assertion, which explains how to get rid of padding
#[derive(Copy, Clone, TrivialType)]
#[repr(C)]
struct PaddedStruct {
    a: u8,
    b: u32,
}

#[derive(Copy, Clone, TrivialType)]
#[repr(u8)]
enum PaddedEnum {
    A { a: u8, b: u8 },
    B { c: u16 },
}

fn main() {}
